const path = "out/hello.txt";
await Bun.write(path, "hello from Bun.write");
const f = Bun.file(path);
console.log("file:", await f.exists(), f.size, f.type, f.name);
console.log("text:", await f.text());
await Bun.write("out/data.json", JSON.stringify({ a: [1, 2] }));
console.log("json:", JSON.stringify(await Bun.file("out/data.json").json()));
console.log("bytes:", (await Bun.file(path).bytes()).length, (await f.arrayBuffer()).byteLength);
console.log("missing exists:", await Bun.file("nope.txt").exists());
const copied = await Bun.write("out/copy.txt", Bun.file(path));
console.log("write returns bytes:", copied);
await Bun.write(Bun.file("out/u8.bin"), new Uint8Array([1, 2, 3]));
console.log("u8 size:", Bun.file("out/u8.bin").size);
console.log("slice:", await Bun.file(path).slice(0, 5).text());

console.log("version:", typeof Bun.version, typeof Bun.revision);
const t0 = Bun.nanoseconds();
Bun.sleepSync(5);
console.log("sleepSync + nanoseconds:", Bun.nanoseconds() - t0 >= 4e6);
console.log("inspect:", Bun.inspect({ a: 1, b: "x" }));
console.log("inspect array:", Bun.inspect([1, "two", [3]]));
console.log("deepEquals:", Bun.deepEquals({ a: [1, { b: 2 }] }, { a: [1, { b: 2 }] }), Bun.deepEquals({ a: 1 }, { a: 2 }));
console.log("deepEquals strict:", Bun.deepEquals({ a: undefined }, {}), Bun.deepEquals({ a: undefined }, {}, true));
console.log("escapeHTML:", Bun.escapeHTML(`<a href="x">Tom & 'Jerry'</a>`));
console.log("stringWidth:", Bun.stringWidth("hello"), Bun.stringWidth("日本語"), Bun.stringWidth("\u001b[31mred\u001b[0m"));
console.log("hash:", Bun.hash("hello"), Bun.hash("hello", 1), Bun.hash.wyhash("abc"));
console.log("crc32:", Bun.hash.crc32("hello"), "adler32:", Bun.hash.adler32("hello"));
console.log("CryptoHasher:", new Bun.CryptoHasher("sha256").update("abc").digest("hex"));
console.log("main:", Bun.main.endsWith("/index.js"));
await Bun.sleep(1);
console.log("peek:", Bun.peek(Promise.resolve(5)), Bun.peek.status(new Promise(() => {})));
import { file as namedFile, version } from "bun";
console.log("bun module:", typeof namedFile, version === Bun.version);
